#!/usr/bin/env python3
"""Build the bundled offline guide from the same structured topics as in-app help."""
import html,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
s=(root/'Web/help-content37.js').read_text(encoding='utf-8')
topics=json.loads(s.split('const helpTopics37 = ',1)[1].strip().removesuffix(';'))
assert len(topics)>=20 and len({t['id'] for t in topics})==len(topics)
esc=html.escape
sections=[]
for t in topics:
    sections.append('<article id="'+esc(t['id'])+'"><h2>'+esc(t['title'])+'</h2><p>'+esc(t['summary'])+'</p><ol>'+''.join('<li>'+esc(v)+'</li>' for v in t['steps'])+'</ol>'+('<h3>使用提示</h3>'+''.join('<p>'+esc(v)+'</p>' for v in t['notes']) if t['notes'] else '')+('<h3>常见问题</h3>'+''.join('<details><summary>'+esc(f['q'])+'</summary><p>'+esc(f['a'])+'</p></details>' for f in t['questions']) if t['questions'] else '')+'</article>')
output='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'"><title>KongScholar 3.8 帮助说明</title><style>
:root{color-scheme:light dark;--bg:#f5f5f5;--panel:#fff;--ink:#242424;--muted:#656565;--line:#ddd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.85 -apple-system,BlinkMacSystemFont,sans-serif}header{padding:28px 32px 18px;border-bottom:1px solid var(--line);background:var(--panel)}h1{font-size:27px;margin:0}h2{font-size:23px;line-height:1.5}h3{font-size:17px}header p{margin:6px 0;color:var(--muted)}input{width:100%;font:inherit;padding:10px 14px;border:1px solid var(--line);border-radius:9px;background:var(--bg);color:var(--ink)}.layout{display:grid;grid-template-columns:235px minmax(0,1fr);gap:24px;padding:24px 32px;max-width:1400px;margin:auto}nav{align-self:start;position:sticky;top:16px;max-height:85vh;overflow:auto}a{color:inherit}nav a{display:block;padding:6px 10px;border-radius:7px;text-decoration:none;font-size:14px}nav a:hover,nav a:focus{background:var(--line)}article{background:var(--panel);padding:22px 28px;margin:0 0 20px;border:1px solid var(--line);border-radius:12px;scroll-margin-top:16px;overflow-wrap:anywhere}article p,li{margin:12px 0}details{padding:8px 0}summary{cursor:pointer;font-weight:600}footer{color:var(--muted);padding:0 32px 32px;font-size:13px}[hidden]{display:none!important}@media(prefers-color-scheme:dark){:root{--bg:#212121;--panel:#292929;--ink:#ececec;--muted:#b0b0b0;--line:#454545}}@media(max-width:700px){.layout{grid-template-columns:1fr;padding:16px}nav{position:static;max-height:230px}header{padding:20px}article{padding:18px}}@media print{header input,nav{display:none}.layout{display:block;padding:0}article{border:0;break-inside:avoid}article[hidden]{display:block!important}body{background:white;color:black}details p{display:block}}
</style><header><h1>KongScholar 帮助说明</h1><p>3.8 · 个人学术工作台 · 著作、论文、讲座与研究</p><label for="search">搜索说明</label><input id="search" type="search" placeholder="例如：日历、KongFolio、备份、返修"><p id="count" role="status"></p></header><div class="layout"><nav aria-label="帮助目录">'''+''.join('<a href="#'+esc(t['id'])+'" data-topic="'+esc(t['id'])+'">'+esc(t['title'])+'</a>' for t in topics)+'</nav><main>'+''.join(sections)+'''<p id="empty" hidden>没有匹配主题，请缩短关键词。</p></main></div><footer>全部说明随安装包离线提供。日历交换遵循 <a href="https://www.rfc-editor.org/rfc/rfc5545">RFC 5545</a> 的受支持子集，具体范围见 iCalendar 主题。</footer><script>
const input=document.querySelector('#search'),articles=[...document.querySelectorAll('article')];function filter(){const q=input.value.trim().toLocaleLowerCase();let count=0;for(const a of articles){a.hidden=!!q&&!a.textContent.toLocaleLowerCase().includes(q);document.querySelector('[data-topic="'+a.id+'"]').hidden=a.hidden;if(!a.hidden)count++;}document.querySelector('#count').textContent=count+'个主题';document.querySelector('#empty').hidden=count!==0;}input.addEventListener('input',filter);filter();
</script></html>'''
(root/'Documentation/使用说明.html').write_text(output,encoding='utf-8')
print('Generated offline guide:',len(topics),'topics')
